library(tidyverse)
library(gt)

Function for cleaning up csv

clean_up_wb_csv &lt;- function(in_file_name, out_file_name) {

  raw_lines &lt;- readLines(in_file_name)

  data_start &lt;- which(str_detect(raw_lines, "^\"Country Name\""))[1]

  cleaned_lines &lt;- raw_lines[data_start:length(raw_lines)]

  writeLines(cleaned_lines, out_file_name)
}

Clean up given data files

clean_up_wb_csv(
  "world_bank_total_population/API_SP.POP.TOTL_DS2_en_csv_v2_267553.csv",
  "population.csv"
)

clean_up_wb_csv(
  "indicator_data_folder/API_NE.DAB.TOTL.KD_DS2_en_csv_v2_9332/API_NE.DAB.TOTL.KD_DS2_en_csv_v2_9332.csv",
  "indicator.csv"
)





population &lt;- read_csv("population.csv")

indicator &lt;- read_csv("indicator.csv")

country_codes &lt;- read_csv("country_codes.csv")





population &lt;- population |&gt;
  filter(`Country Code` %in% country_codes$country_code)

indicator &lt;- indicator |&gt;
  filter(`Country Code` %in% country_codes$country_code)




